head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > calendarValueType]<br/>Calendar 컴포넌트에 입력할 수 있는 날짜 및 시간의 형식을 설정합니다. 팝업 달력의 UI 도 속성값에 맞게 변경되어 표시됩니다.",
    "validation" : [
        "미설정(기본값 'yearMonthDate') 시 입력값을 년월일(yyyyMMdd, 8자리) 형식으로 설정합니다.",
        "'yearMonthDate' 설정 시 입력값을 년월일(yyyyMMdd, 8자리) 형식으로 설정합니다.",
        "'yearMonth' 설정 시 입력값을 년월(yyyyMM, 6자리) 형식으로 설정합니다.",
        "'yearMonthDateHour' 설정 시 입력값을 년월일시(yyyyMMddHH, 10자리) 형식으로 설정합니다.",
        "'yearMonthDateTime' 설정 시 입력값을 년월일시분(yyyyMMddHHmm, 12자리) 형식으로 설정합니다.",
        "'yearMonthDateTimeSec' 설정 시 입력값을 년월일시분초(yyyyMMddHHmmSS, 14자리) 형식으로 설정합니다.",
        "'yearMonthDate' 설정 시 날짜 그리드(6x7 셀), 오늘 버튼, 현재 날짜 표시, 취소/리셋 버튼이 Footer 에 렌더링됩니다.",
        "'yearMonth' 설정 시 날짜 그리드가 숨겨지고, Header 에 확인/닫기 버튼이 추가됩니다.",
        "'yearMonth' 설정 시 calendarClass 속성값이 'classYearMonth_' 접두사로 자동 변환됩니다. (예: class1 → classYearMonth_class1)",
        "'yearMonth' 설정 시 getSelectedDay() 메소드는 빈 문자열을 반환합니다.",
        "'yearMonthDateHour' 설정 시 날짜 그리드와 함께 Footer 에 시간(Hour) SelectBox 1개가 추가로 렌더링됩니다.",
        "'yearMonthDateTime' 설정 시 날짜 그리드와 함께 Footer 에 시간(Hour)과 분(Minute) SelectBox 가 추가로 렌더링됩니다.",
        "'yearMonthDateTimeSec' 설정 시 날짜 그리드와 함께 Footer 에 시간(Hour), 분(Minute), 초(Second) SelectBox 가 추가로 렌더링됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        calendarValueType : con_calendarValueType.getText(),
        calendarClass : con_calendarClass.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



// [공통] 적용된 calendarValueType, 입력값 길이/포맷
scwin.getValueTypeInfo = function () {
    let valueType = target1.options.calendarValueType;
    let inputValue = target1.getValue();
    let formatted = target1.getFormattedValue();

    // validation: 미설정 시 기본값 'yearMonthDate' / 각 enum 값 설정 시 해당 값 적용
    wf_body_bottom.getObj("scwin").setReturnValue("[calendarValueType 적용값] " + valueType);
    // validation: yearMonthDate=8자리, yearMonth=6자리, yearMonthDateHour=10자리, yearMonthDateTime=12자리, yearMonthDateTimeSec=14자리
    wf_body_bottom.getObj("scwin").setReturnValue("[입력값(getValue) / 길이] '" + inputValue + "' / " + inputValue.length + "자리");
    wf_body_bottom.getObj("scwin").setReturnValue("[포맷값(getFormattedValue)] '" + formatted + "'");
}



// [yearMonthDate/Hour/Time/TimeSec 공용] 날짜 그리드(6x7 셀) 렌더링 여부
scwin.getDateGridInfo = function () {
    let dateCells = target1.render.querySelectorAll('td[class*="w2calendar_col_date"]');
    // yearMonth 모드에선 DOM 에 셀은 있지만 부모 그리드가 display:none 으로 숨겨지므로 실제 표시 여부는 offsetWidth/Height 로 판단
    let isVisible = false;
    if (dateCells.length > 0) {
        isVisible = dateCells[0].offsetWidth > 0 && dateCells[0].offsetHeight > 0;
    }
    // validation: yearMonthDate/Hour/Time/TimeSec → 날짜 그리드 표시 / yearMonth → 날짜 그리드 숨김
    wf_body_bottom.getObj("scwin").setReturnValue("[날짜 그리드 셀 수 / 표시 여부] " + dateCells.length + "개 / " + (isVisible ? "표시됨" : "숨김"));
}



// [yearMonthDate 전용] Footer 오늘/현재/취소/리셋 버튼
scwin.getFooterBasicInfo = function () {
    let r = target1.render;
    let goToday = r.querySelector('.w2calendar_go_today');
    let currentDate = r.querySelector('[id$="_currentDate"]');
    let dateCancel = r.querySelector('.w2calendar_date_cancel') || r.querySelector('.w2calendar_time_cancel');
    let dateReset = r.querySelector('.w2calendar_date_reset') || r.querySelector('.w2calendar_time_reset');

    // validation: yearMonthDate 설정 시 오늘 버튼, 현재 날짜 표시, 취소/리셋 버튼이 Footer 에 렌더링됨
    wf_body_bottom.getObj("scwin").setReturnValue("[Footer 오늘/현재/취소/리셋 렌더링] 오늘=" + (goToday ? "O" : "X") + ", 현재=" + (currentDate ? "O" : "X") + ", 취소=" + (dateCancel ? "O" : "X") + ", 리셋=" + (dateReset ? "O" : "X"));
}



// [Hour/Time/TimeSec 전용] Footer 시간 SelectBox (필요한 것만 출력)
scwin.getFooterTimeBox = function (boxes) {
    let r = target1.render;
    let result = boxes.map(function (b) {
        let found = r.querySelector('[id$="_selectbox_' + b + '"]');
        let label = (b === 'hour') ? '시간(Hour)' : (b === 'minute') ? '분(Minute)' : '초(Second)';
        return label + '=' + (found ? "렌더링됨" : "미렌더링");
    }).join(', ');
    // validation: yearMonthDateHour=Hour 1개 / yearMonthDateTime=Hour+Minute / yearMonthDateTimeSec=Hour+Minute+Second SelectBox 추가
    wf_body_bottom.getObj("scwin").setReturnValue("[Footer 시간 SelectBox] " + result);
}



// [yearMonth 전용] Header 확인/닫기 버튼
scwin.getHeaderInfo = function () {
    let r = target1.render;
    let okBtn = r.querySelector('div.w2calendar_header_btn_ok');
    let closeBtn = r.querySelector('div.w2calendar_header_btn_close');

    // validation: yearMonth 설정 시 Header 에 확인/닫기 버튼 추가
    wf_body_bottom.getObj("scwin").setReturnValue("[Header 확인/닫기 버튼 렌더링] 확인=" + (okBtn ? "O" : "X") + ", 닫기=" + (closeBtn ? "O" : "X"));
}



// [yearMonth 전용] calendarClass 자동 변환(classYearMonth_ 접두사) + 최상위 div className
scwin.getClassInfo = function () {
    // validation: yearMonth 설정 시 calendarClass 가 'classYearMonth_' 접두사로 자동 변환됨 (예: class1 → classYearMonth_class1)
    wf_body_bottom.getObj("scwin").setReturnValue("[calendarClass 옵션값(자동 변환 후)] '" + target1.options.calendarClass + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("[최상위 div className] '" + target1.render.className + "'");
}



// [yearMonth 전용] getSelectedDay() 빈 문자열 반환
scwin.getSelectedDayInfo = function () {
    let selectedDay = target1.getSelectedDay();
    // validation: yearMonth 설정 시 getSelectedDay() 메소드는 빈 문자열 반환
    wf_body_bottom.getObj("scwin").setReturnValue("[getSelectedDay() 반환] '" + selectedDay + "' (빈 문자열 여부: " + (selectedDay === '' ? "예" : "아니오") + ")");
}



// calendarValueType 설정값별 분기 — 각 타입에 필요한 검증만 출력
scwin.btn_getInfo_onclick = function (e) {
    // 공통: 적용값 + 입력값 포맷
    scwin.getValueTypeInfo();

    // 분기: 미설정은 기본값 'yearMonthDate' 와 동일 동작
    let valueType = target1.options.calendarValueType || 'yearMonthDate';

    if (valueType === 'yearMonthDate') {
        scwin.getDateGridInfo();
        scwin.getFooterBasicInfo();
    } else if (valueType === 'yearMonth') {
        scwin.getDateGridInfo();
        scwin.getHeaderInfo();
        scwin.getClassInfo();
        scwin.getSelectedDayInfo();
    } else if (valueType === 'yearMonthDateHour') {
        scwin.getDateGridInfo();
        scwin.getFooterTimeBox(['hour']);
    } else if (valueType === 'yearMonthDateTime') {
        scwin.getDateGridInfo();
        scwin.getFooterTimeBox(['hour', 'minute']);
    } else if (valueType === 'yearMonthDateTimeSec') {
        scwin.getDateGridInfo();
        scwin.getFooterTimeBox(['hour', 'minute', 'second']);
    }
}



scwin.target1_onclick = function (e) {
    setTimeout(() => {
        scwin.getValueTypeInfo();
    }, 100);
}
